        int n = scanner.nextInt();
        int[] arr = new int[n];
        int minIndex = -1, maxIndex = -1;
        int minVal = Integer.MAX_VALUE;
        int maxVal = Integer.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
            if (arr[i] < minVal) {
                minVal = arr[i];
                minIndex = i;
            }
            if (arr[i] > maxVal) {
                maxVal = arr[i];
                maxIndex = i;
            }
        }

        if (minIndex != maxIndex && n > 0) {
            int temp = arr[minIndex];
            arr[minIndex] = arr[maxIndex];
            arr[maxIndex] = temp;
        }

        String result = "";
        for (int i = 0; i < n; i++) {
            result += arr[i] + (i == n - 1 ? "" : " ");
        }
        System.out.println(result);
    }
}

