public int sumPath(int row, int col) {
    int sum = grid[row][col];
    Location next = getNextLoc(row, col);

    while (next != null) {
        row = next.getRow();
        col = next.getCol();
        sum += grid[row][col];
        next = getNextLoc(row, col);
    }

    return sum;
}

public int sumPath(int row, int col) {
    // Base Case: Path ends (getNextLoc returns null)
    Location next = getNextLoc(row, col);

    if (next == null) {
        return grid[row][col]; // Path ends, return last element
    }

    // Recursive Step: Sum current element and the rest of the path
    int nextRow = next.getRow();
    int nextCol = next.getCol();

    return grid[row][col] + sumPath(nextRow, nextCol);
}

