public int findAvailableSeats(int numSeats) {
    for (int r = 0; r < seats.length; r++) {
        for (int c = 0; c <= seats[r].length - numSeats; c++) {
            boolean foundBlock = true;
            // Check for numSeats contiguous available seats starting at (r, c)
            for (int k = 0; k < numSeats; k++) {
                if (!seats[r][c + k]) { // if occupied
                    foundBlock = false;
                    break;
                }
            }

            if (foundBlock) {
                return c; // Return starting column index
            }
        }
    }
    return -1; // No block found in any row
}

