public int getMaxLength(int start, int end) {
    if (start > end || words.length == 0) {
        // Should not happen based on precondition, but safe practice
        return 0;
    }

    int maxLength = words[start].length();

    for (int i = start + 1; i <= end; i++) {
        int currentLength = words[i].length();
        if (currentLength > maxLength) {
            maxLength = currentLength;
        }
    }
    return maxLength;
}

