public void insertValue(int val) {
    for (int i = 0; i < list.size(); i++) {
        if (val < list.get(i)) {
            list.add(i, val);
            return;
        }
    }
    // If val is the largest, add it to the end
    list.add(val);
}

public static ArrayList<Integer> sortList(ArrayList<Integer> unsorted) {
    // Create a new sorter object to manage the sorted list
    InsertionSorter sorter = new InsertionSorter(); 

    for (int val : unsorted) {
        // Use the instance method to insert/sort the value
        sorter.insertValue(val);
    }

    // Return the internal sorted list of the sorter object
    return sorter.list; 
}

public static boolean isSorted(int[] arr) {
    return isSorted(arr, arr.length - 1);
}

private static boolean isSorted(int[] arr, int k) {
    if (k == 0) {
        return true; // Base case: first element is trivially sorted
    }
    if (arr[k] <= arr[k - 1]) {
        return false; // Not strictly increasing
    }
    // Recursive step
    return isSorted(arr, k - 1);
}

public static int countOccurrences(int[] arr, int target) {
    return countOccurrences(arr, target, arr.length - 1);
}

private static int countOccurrences(int[] arr, int target, int k) {
    if (k < 0) {
        return 0; // Base case: end of array reached
    }

    // Check current element
    int count = 0;
    if (arr[k] == target) {
        count = 1;
    }

    // Recursive step: add current count to the count from the rest of the array
    return count + countOccurrences(arr, target, k - 1);
}

public void addTask(String name, int duration) {
    for (int i = 0; i < taskNames.size(); i++) {
        if (taskNames.get(i).equals(name)) {
            durations.set(i, duration); // Replace existing duration
            return;
        }
    }
    // Task not found, add to the end
    taskNames.add(name);
    durations.add(duration);
}

public int getTotalDuration(int minDuration) {
    int total = 0;
    for (int duration : durations) {
        if (duration >= minDuration) {
            total += duration;
        }
    }
    return total;
}
